providers:
{
      provide: 'CONNECTOR_REGISTRY_BOOTSTRAP',
      useFactory: (registry: ConnectorRegistry) => {
        registry.registerCategory(MAIL_CATEGORY);
        registry.registerCategory(DMS_CATEGORY);
        registry.registerCategory(HOME_AUTOMATION_CATEGORY);
        registry.registerCategory(STORAGE_CATEGORY);
        registry.registerCategory(SCANNER_SFTP_CATEGORY);
        registry.registerPlugin(new GmailMailConnector());
        registry.registerPlugin(new OutlookMailConnector());
        registry.registerPlugin(new PaperlessDmsConnector());
        registry.registerPlugin(new HomeAssistantHomeAutomationConnector());
        registry.registerPlugin(new AmazonS3StorageConnector());
        registry.registerPlugin(new SftpFetchConnector());
        return true;
      },
      inject: [ConnectorRegistry],
    }

{
      provide: 'DOCUMENT_PIPELINE_BOOTSTRAP',
      useFactory: (
        registry: DocumentPipelineRegistry,
        labelMatching: LabelMatchingDocumentPipelineStep,
        embedding: EmbeddingSuggestionsDocumentPipelineStep,
        globalFields: GlobalRecognizedFieldsDocumentPipelineStep,
        labelFields: LabelAttachedFieldsDocumentPipelineStep,
        duplicates: DuplicateDetectionDocumentPipelineStep
      ) => {
        registry.register(labelMatching);
        registry.register(embedding);
        registry.register(globalFields);
        registry.register(labelFields);
        registry.register(duplicates);
        return true;
      },
      inject: [
        DocumentPipelineRegistry,
        LabelMatchingDocumentPipelineStep,
        EmbeddingSuggestionsDocumentPipelineStep,
        GlobalRecognizedFieldsDocumentPipelineStep,
        LabelAttachedFieldsDocumentPipelineStep,
        DuplicateDetectionDocumentPipelineStep,
      ],
    }

{
      provide: PG_POOL,
      useFactory: () => {
        const url = process.env.DATABASE_URL;
        if (!url) throw new Error('DATABASE_URL is required');
        return new pg.Pool({ connectionString: url });
      },
    }

