import { Inject, Injectable, Logger, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { Queue, Worker } from 'bullmq';
import type IORedis from 'ioredis';

import {
  DOCUMENT_CHAT_THREAD_REPOSITORY,
  type DocumentChatThreadRepository,
} from '../../../shared/domain/ports.js';
import {
  isRecord,
  parseOptionalString,
  parseString,
} from '../../../shared/infrastructure/database/row-parse.js';
import {
  createValkeyConnection,
  waitForValkeyReady,
} from '../../../shared/infrastructure/valkey/valkey-connection.js';
import {
  type DocumentChatGenerationJobPayload,
  RunDocumentChatGenerationUseCase,
} from '../application/run-document-chat-generation.use-case.js';

const QUEUE_NAME = 'document-chat-generation';

function parseJobPayload(data: unknown): DocumentChatGenerationJobPayload | null {
  if (!isRecord(data)) {
    return null;
  }
  const messageId = parseString(data.messageId);
  const threadId = parseString(data.threadId);
  const userId = parseString(data.userId);
  const userMessage = parseString(data.userMessage);
  if (!messageId || !threadId || !userId) {
    return null;
  }
  const documentId = parseOptionalString(data.documentId) ?? undefined;
  return { messageId, threadId, userId, userMessage, documentId };
}

@Injectable()
export class DocumentChatGenerationQueueService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(DocumentChatGenerationQueueService.name);
  private connection!: IORedis;
  private queue!: Queue;
  private worker!: Worker;

  constructor(
    private readonly runGeneration: RunDocumentChatGenerationUseCase,
    @Inject(DOCUMENT_CHAT_THREAD_REPOSITORY)
    private readonly threads: DocumentChatThreadRepository
  ) {}

  async onModuleInit(): Promise<void> {
    this.connection = createValkeyConnection();
    await waitForValkeyReady(this.connection);

    const concurrency = documentChatGenerationConcurrency();

    this.queue = new Queue(QUEUE_NAME, { connection: this.connection });

    this.worker = new Worker(
      QUEUE_NAME,
      async (job) => {
        const payload = parseJobPayload(job.data);
        if (!payload) {
          throw new Error('Invalid document chat generation job payload');
        }
        await this.runGeneration.execute(payload);
      },
      { connection: this.connection, concurrency }
    );

    this.worker.on('failed', (job, err) => {
      const payload = job ? parseJobPayload(job.data) : null;
      void this.markJobFailed(payload, err);
    });
  }

  private async markJobFailed(
    payload: DocumentChatGenerationJobPayload | null,
    err: Error
  ): Promise<void> {
    if (!payload?.messageId || !payload.userId) {
      return;
    }
    try {
      const existing = await this.threads.findMessageForUser(payload.messageId, payload.userId);
      if (
        !existing ||
        existing.generationStatus === 'done' ||
        existing.generationStatus === 'failed'
      ) {
        return;
      }
      await this.threads.updateMessageGeneration(payload.messageId, {
        generationStatus: 'failed',
        generationPhase: null,
        errorCode: 'generation_failed',
        errorDetail: err.message,
        content: existing.content,
      });
      if (payload.threadId) {
        await this.threads.touchThread(payload.threadId);
      }
    } catch (markErr) {
      this.logger.warn(`Could not mark chat generation failed: ${String(markErr)}`);
    }
  }

  async isJobQueuedOrActive(messageId: string): Promise<boolean> {
    const job = await this.queue.getJob(messageId);
    if (!job) {
      return false;
    }
    const state = await job.getState();
    return state === 'active' || state === 'waiting' || state === 'delayed';
  }

  async enqueue(payload: DocumentChatGenerationJobPayload): Promise<void> {
    const existing = await this.queue.getJob(payload.messageId);
    if (existing) {
      await existing.remove();
    }
    await this.queue.add('generate', payload, {
      jobId: payload.messageId,
      removeOnComplete: 200,
      removeOnFail: 100,
    });
  }

  async onModuleDestroy(): Promise<void> {
    await this.worker.close();
    await this.queue.close();
    await this.connection.quit();
  }
}

function documentChatGenerationConcurrency(): number {
  const raw = process.env.DOCUMENT_CHAT_GENERATION_CONCURRENCY;
  if (!raw) {
    return 1;
  }
  const parsed = Number.parseInt(raw, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 1;
}

// SPDX-FileCopyrightText: 2026 Thomas Faust
// SPDX-License-Identifier: LicenseRef-Docuvate-SUL-1.0
import { type ExtractedField,type ExtractionBlock, suggestionStorageKey } from '@docuvate/contracts';
import type pg from 'pg';

import {
  parseNumber,
  parseOptionalNumber,
  parseString,
  requireRecord,
} from '../../../shared/infrastructure/database/row-parse.js';
import {
  loadDocumentFieldValues,
  replaceDocumentFieldValues,
} from '../../search/infrastructure/document-field-value-index.js';

type Db = pg.Pool | pg.PoolClient;

export function mergeExtractionFieldRows(
  fields: ExtractedField[],
  fieldSuggestions: { key: string; value: string; confidence?: number }[] = []
): ExtractedField[] {
  const rows = [...fields];
  for (const suggestion of fieldSuggestions) {
    const semantic = suggestion.key.trim().toLowerCase();
    const value = suggestion.value.trim();
    if (!semantic || !value) continue;
    rows.push({
      key: suggestionStorageKey(semantic),
      value,
      confidence: suggestion.confidence ?? 0.45,
    });
  }
  return rows;
}

/** Replaces all field values of a document (extraction result or user edit). */
export async function replaceDocumentExtractionFields(
  client: Db,
  documentId: string,
  userId: string,
  fields: ExtractedField[]
): Promise<void> {
  await replaceDocumentFieldValues(client, documentId, userId, fields);
}

/** Replaces all layout blocks of a document, keeping their order. */
export async function replaceDocumentExtractionBlocks(
  client: Db,
  documentId: string,
  blocks: ExtractionBlock[]
): Promise<void> {
  await client.query(`DELETE FROM document_extraction_blocks WHERE document_id = $1`, [documentId]);
  for (const [position, block] of blocks.entries()) {
    await client.query(
      `INSERT INTO document_extraction_blocks (
         document_id, position, page, block_index, x, y, width, height, text
       ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
      [
        documentId,
        position,
        block.page,
        block.blockIndex ?? null,
        block.x,
        block.y,
        block.width,
        block.height,
        block.text,
      ]
    );
  }
}

async function loadBlocks(
  client: Db,
  documentIds: string[]
): Promise<Map<string, ExtractionBlock[]>> {
  const out = new Map<string, ExtractionBlock[]>();
  if (documentIds.length === 0) return out;
  const result = await client.query(
    `SELECT document_id, page, block_index, x, y, width, height, text
     FROM document_extraction_blocks
     WHERE document_id = ANY($1::uuid[])
     ORDER BY document_id, position`,
    [documentIds]
  );
  for (const raw of result.rows) {
    const row = requireRecord(raw);
    const documentId = parseString(row.document_id);
    const block: ExtractionBlock = {
      page: parseNumber(row.page),
      x: parseNumber(row.x),
      y: parseNumber(row.y),
      width: parseNumber(row.width),
      height: parseNumber(row.height),
      text: parseString(row.text),
    };
    const blockIndex = parseOptionalNumber(row.block_index);
    if (blockIndex != null) {
      block.blockIndex = blockIndex;
    }
    const list = out.get(documentId) ?? [];
    list.push(block);
    out.set(documentId, list);
  }
  return out;
}

export interface DocumentExtractionRows {
  fields: ExtractedField[];
  blocks: ExtractionBlock[];
}

/** Field values and layout blocks for many documents (two queries in total). */
export async function loadExtractionForDocuments(
  client: Db,
  documentIds: string[]
): Promise<Map<string, DocumentExtractionRows>> {
  const [fields, blocks] = await Promise.all([
    loadDocumentFieldValues(client, documentIds),
    loadBlocks(client, documentIds),
  ]);
  const out = new Map<string, DocumentExtractionRows>();
  for (const id of documentIds) {
    out.set(id, { fields: fields.get(id) ?? [], blocks: blocks.get(id) ?? [] });
  }
  return out;
}

export async function loadExtractionForDocument(
  client: Db,
  documentId: string
): Promise<DocumentExtractionRows> {
  const map = await loadExtractionForDocuments(client, [documentId]);
  return map.get(documentId) ?? { fields: [], blocks: [] };
}

