import type { DuplicateDetectionConfig } from './duplicate-detection.config.js';
import type { DuplicateDocumentSignals } from './duplicate-document-signals.js';

export type DuplicateGateRejectionReason = 'conflicting_reporting_years' | 'page_count_mismatch';

export interface EmbeddingDuplicateGateResult {
  accept: boolean;
  reason?: DuplicateGateRejectionReason;
}

const CALENDAR_YEAR_RE = /\b(19|20)\d{2}\b/g;
const DECEMBER_CLOSING_DATE_RE =
  /(?:31\s*\.\s*12\s*\.?|31\s*\.\s*Dez(?:ember)?)\s*\.?\s*((?:19|20)\d{2})/gi;

/** Collect likely fiscal/reporting years from filename, title, OCR sample, and document date. */
export function collectReportingYears(signals: DuplicateDocumentSignals): number[] {
  const years = new Set<number>();
  const textParts = [signals.filename, signals.title, signals.extractedTextSample];

  for (const part of textParts) {
    for (const match of part.matchAll(CALENDAR_YEAR_RE)) {
      const year = Number(match[0]);
      if (year >= 1990 && year <= 2099) years.add(year);
    }
    for (const match of part.matchAll(DECEMBER_CLOSING_DATE_RE)) {
      const year = Number(match[1]);
      if (year >= 1990 && year <= 2099) years.add(year);
    }
  }

  if (signals.documentDateYear != null && signals.documentDateYear >= 1990) {
    years.add(signals.documentDateYear);
  }

  return [...years].sort((a, b) => a - b);
}

export function reportingYearsConflict(yearsA: number[], yearsB: number[]): boolean {
  if (yearsA.length === 0 || yearsB.length === 0) return false;
  const setB = new Set(yearsB);
  for (const year of yearsA) {
    if (setB.has(year)) return false;
  }
  return true;
}

function pageCountBlocksEmbedding(
  left: DuplicateDocumentSignals,
  right: DuplicateDocumentSignals,
  similarity: number,
  config: DuplicateDetectionConfig
): boolean {
  if (left.pageCount == null || right.pageCount == null) return false;
  if (similarity >= config.pageCountGateMaxSimilarity) return false;
  return Math.abs(left.pageCount - right.pageCount) >= config.pageCountMinDifference;
}

/**
 * Hybrid gates for embedding-based duplicate candidates. Hash matches bypass this entirely.
 */
export function evaluateEmbeddingDuplicateCandidate(
  source: DuplicateDocumentSignals,
  candidate: DuplicateDocumentSignals,
  similarity: number,
  config: DuplicateDetectionConfig
): EmbeddingDuplicateGateResult {
  const sourceYears = collectReportingYears(source);
  const candidateYears = collectReportingYears(candidate);
  if (reportingYearsConflict(sourceYears, candidateYears)) {
    return { accept: false, reason: 'conflicting_reporting_years' };
  }

  if (pageCountBlocksEmbedding(source, candidate, similarity, config)) {
    return { accept: false, reason: 'page_count_mismatch' };
  }

  return { accept: true };
}

// SPDX-FileCopyrightText: 2026 Thomas Faust
// SPDX-License-Identifier: LicenseRef-Docuvate-SUL-1.0
export interface DuplicateDetectionConfig {
  /** Minimum cosine similarity for embedding-based duplicate candidates. */
  embeddingThreshold: number;
  maxEmbeddingCandidates: number;
  /**
   * When both documents have a known page count from extraction blocks, reject embedding
   * matches if the counts differ by at least this amount (unless similarity is very high).
   */
  pageCountMinDifference: number;
  /** Embedding similarity at or above this value bypasses the page-count gate. */
  pageCountGateMaxSimilarity: number;
}

function parseFloatEnv(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw == null || raw.trim() === '') return fallback;
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

function parseIntEnv(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw == null || raw.trim() === '') return fallback;
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) ? n : fallback;
}

export function readDuplicateDetectionConfig(): DuplicateDetectionConfig {
  return {
    embeddingThreshold: parseFloatEnv('DUPLICATE_EMBEDDING_THRESHOLD', 0.88),
    maxEmbeddingCandidates: parseIntEnv('DUPLICATE_MAX_EMBEDDING_CANDIDATES', 8),
    pageCountMinDifference: parseIntEnv('DUPLICATE_PAGE_COUNT_MIN_DIFF', 3),
    pageCountGateMaxSimilarity: parseFloatEnv('DUPLICATE_PAGE_COUNT_GATE_MAX_SIMILARITY', 0.95),
  };
}

// SPDX-FileCopyrightText: 2026 Thomas Faust
// SPDX-License-Identifier: LicenseRef-Docuvate-SUL-1.0
import type { ExtractionBlock } from '@docuvate/contracts';

import {
  isRecord,
  parseNumber,
} from '../../../shared/infrastructure/database/row-parse.js';
import type { DocumentEntity } from '../../documents/domain/document.entity.js';

export interface DuplicateDocumentSignals {
  documentId: string;
  filename: string;
  title: string;
  documentDateYear: number | null;
  extractedTextSample: string;
  pageCount: number | null;
}

export interface DuplicateEmbeddingPeerRow {
  documentId: string;
  embedding: number[];
  filename: string;
  title: string;
  documentDate: Date | null;
  extractedText: string | null;
  extractedFields: unknown;
}

export function pageCountFromBlocks(blocks: ExtractionBlock[] | undefined): number | null {
  if (!blocks || blocks.length === 0) return null;
  let max = 0;
  for (const block of blocks) {
    if (Number.isFinite(block.page) && block.page > max) max = block.page;
  }
  return max > 0 ? max : null;
}

export function pageCountFromExtractedFields(raw: unknown): number | null {
  if (!isRecord(raw)) return null;
  const blocks = raw.blocks;
  if (!Array.isArray(blocks)) return null;
  let max = 0;
  for (const item of blocks) {
    if (!isRecord(item)) continue;
    const page = parseNumber(item.page, Number.NaN);
    if (Number.isFinite(page) && page > max) max = page;
  }
  return max > 0 ? max : null;
}

export function signalsFromDocument(doc: DocumentEntity): DuplicateDocumentSignals {
  return {
    documentId: doc.id,
    filename: doc.filename,
    title: doc.title,
    documentDateYear: doc.documentDate ? doc.documentDate.getUTCFullYear() : null,
    extractedTextSample: (doc.extraction?.text ?? '').slice(0, 8000),
    pageCount: pageCountFromBlocks(doc.extraction?.blocks),
  };
}

export function signalsFromEmbeddingPeer(row: DuplicateEmbeddingPeerRow): DuplicateDocumentSignals {
  return {
    documentId: row.documentId,
    filename: row.filename,
    title: row.title,
    documentDateYear: row.documentDate ? row.documentDate.getUTCFullYear() : null,
    extractedTextSample: (row.extractedText ?? '').slice(0, 8000),
    pageCount: pageCountFromExtractedFields(row.extractedFields),
  };
}

