    return this.acceptRecommendation.execute(session.user.id, {
      recommendationId: decodeURIComponent(id),
      proposedName: body.proposedName,
      tagId: body.tagId,
      keepTagId: body.keepTagId,
      removeTagId: body.removeTagId,
      color: body.color,
    });
