    @Session() session: AuthSession,
    @Param('id') id: string,
    @Body() body: DismissLabelRecommendationRequestDto
  ): Promise<OkResponseDto> {
    await this.dismissRecommendation.execute(session.user.id, decodeURIComponent(id), body);
    return { ok: true };
