/** Rough minimum container mem_limit for loaded inference (GiB). */
const MODEL_MIN_GIB: Record<string, number> = {
  'qwen2.5:3b': 2.5,
  'llama3.2:3b': 2.5,
  'gemma3:4b': 4.5,
  'qwen3:4b': 5,
  'phi4-mini:3.8b-q4_K_M': 3.5,
  'qwen2.5:7b': 6,
};

export function parseMemLimitToGiB(raw: string | undefined | null): number | null {
  if (!raw?.trim()) {
    return null;
  }
  const normalized = raw.trim().toLowerCase();
  const match = /^(\d+(?:\.\d+)?)(g|m|b)?$/.exec(normalized);
  if (!match) {
    return null;
  }
  const value = Number.parseFloat(match[1]);
  const unitChar = match[2];
  const unit = unitChar === 'g' || unitChar === 'm' || unitChar === 'b' ? unitChar : 'b';
  if (unit === 'g') {
    return value;
  }
  if (unit === 'm') {
    return value / 1024;
  }
  return value / (1024 * 1024 * 1024);
}

export function ollamaMemLimitGiBFromEnv(): number | null {
  return parseMemLimitToGiB(process.env.OLLAMA_MEM_LIMIT ?? '3g');
}

export function modelMinGiB(model: string): number {
  const tag = model.trim().toLowerCase();
  if (Object.hasOwn(MODEL_MIN_GIB, tag)) {
    return MODEL_MIN_GIB[tag];
  }
  const base = tag.split(':')[0] ?? tag;
  return MODEL_MIN_GIB[base] ?? 3;
}

export function modelFitsOllamaMemLimit(model: string, limitGiB: number | null): boolean {
  if (limitGiB == null) {
    return true;
  }
  return limitGiB + 0.05 >= modelMinGiB(model);
}

// SPDX-FileCopyrightText: 2026 Thomas Faust
// SPDX-License-Identifier: LicenseRef-Docuvate-SUL-1.0
/** Heuristic: block large Ollama models on CPU-only / low-VRAM hosts. */
/** 4B–8B Q4 models are treated as CPU-safe; gate from ~9B upward. */
const LARGE_MODEL_PATTERN = /(?:^|[/:_-])(9b|13b|14b|20b|30b|34b|70b|72b|405b)(?:$|[/:_-])/i;

const LARGE_MODEL_KEYWORDS = /\b(70b|405b|mixtral|llama-?3\.1|llama3\.1|qwen2\.5-72b)\b/i;

export function ollamaModelLikelyNeedsGpu(model: string): boolean {
  const normalized = model.trim().toLowerCase();
  if (!normalized) {
    return false;
  }
  if (LARGE_MODEL_PATTERN.test(normalized)) {
    return true;
  }
  return LARGE_MODEL_KEYWORDS.test(normalized);
}

export function ollamaAvailableForHardware(
  model: string,
  hardware: { capabilities: { largeLocalLlm: boolean } } | null
): boolean {
  if (!hardware) {
    return true;
  }
  if (!ollamaModelLikelyNeedsGpu(model)) {
    return true;
  }
  return hardware.capabilities.largeLocalLlm;
}

