import { Algorithm, hash, verify } from '@node-rs/argon2';

export async function hashSftpIngressPassword(plain: string): Promise<string> {
  return hash(plain, {
    algorithm: Algorithm.Argon2id,
    memoryCost: 19456,
    timeCost: 2,
    parallelism: 1,
  });
}

