        await upsertVocabularyTerms(
          queryRunner,
          doc.user_id,
          text.slice(0, DOCUMENT_TEXT_SLICE),
          'document'
        );
      }
      await upsertVocabularyTerms(queryRunner, doc.user_id, doc.title ?? '', 'document');
